        u32 n = len - part * STORE_FW_PART < STORE_FW_PART ? len - part * STORE_FW_PART : STORE_FW_PART;

        if (part + 1 == parts && !fw_verify(kind, id, tag, parts, payload, len)) {
            r = STORE_ERR_VERIFY;
            break;
