content.content:
/* Reads one valid sector whole and takes its records. Pass 1: the
 * base's keys, the counts, and for the head where its erased tail
 * begins; which sectors hold a firmware kind's record. Since BR-12, on
 * those sectors again, pass 2: each payload's committed write, the
 * highest tag of a last part newer than the reset; pass 3: the parts of
 * the committed writes. */
static void scan(u32 s, u32 pass)
{
    u32 off = BLOCK, end = BLOCK;

    read(sector_addr(s), sector_buf, STORE_SECTOR);
    while (off + BLOCK <= STORE_SECTOR) {
        const u8 *p = sector_buf + off;
        int len, k;
        u32 seq, tag;

        if (blank(p, BLOCK)) {
            off += BLOCK;
            continue;
        }
        len = record_check(p, STORE_SECTOR - off);
        if (len < 0) {
            if (pass == 1 && len == -2)
                sb_store.crc_bad++;
            else if (pass == 1)
                sb_store.skipped++;
            off += BLOCK;
            end = off;
            continue;
        }
        seq = rd32(p + 8);
        off += record_size((u32)len);
        if (!fw_kind(p[1])) {
            end = off;
            if (pass != 1)
                continue;
            if (seq >= next_seq)
                next_seq = seq + 1;
            k = key_of(p[1], p[2]);
            if (k < 0)
                sb_store.unknown++;
            else if (seq > key[k].seq || !key[k].addr) {
                key[k].seq = seq;
                key[k].addr = sector_addr(s) + off - record_size((u32)len);
            }
            continue;
        }
        end = off;
        /* A firmware kind's part (BR-9): its index below its count, its
         * tag in its payload's first word. */
        if (!(p[6] < p[7] && p[7] <= STORE_FW_PARTS && (u32)len >= STORE_FW_TAG)) {
            if (pass == 1)
                sb_store.unknown++;
            continue;
        }
        tag = rd32(p + HEADER);
        if (pass == 1) {
            if (seq >= next_seq)
                next_seq = seq + 1;
            fw_sectors |= 1u << s;
        } else if (pass == 2) {
            if (p[6] + 1u != p[7] || seq < reset_seq)
                continue;
            k = fw_commit(p[1], p[2], 1);
            if (k < 0)
                sb_store.unknown++;
            else if (!fwc[k].parts || tag > fwc[k].tag) {
                fwc[k].parts = p[7];
                fwc[k].tag = tag;
            }
        } else {
            int c = fw_commit(p[1], p[2], 0);

            if (seq < reset_seq) {
                sb_store.voided++;
                continue;
            }
            if (c < 0 || fwc[c].tag != tag || fwc[c].parts != p[7]) {
                sb_store_fw.stale++;
                continue;
            }
            k = fw_key(p[1], p[2], tag, p[6], 1);
            if (k < 0)
                sb_store.unknown++;
            else if (seq > key[k].seq || !key[k].addr) {
                key[k].seq = seq;
                key[k].addr = sector_addr(s) + off - record_size((u32)len);
                fwk[k - KEYS].parts = p[7];
            }
        }
    }
    if (pass == 1 && s == head)
        append = end;
}

    if (r)
        return r;
    head = n;
    head_seq++;
    append = BLOCK;
    sb_store.head = head;
    sb_store.head_seq = head_seq;
    return STORE_OK;
}

/* Keys whose newest record is in sector s. */
static u32 live_in(u32 s)
{
    u32 k, n = 0, a = sector_addr(s);

    for (k = 0; k < ALL_KEYS; k++)
        n += key[k].addr >= a && key[k].addr < a + STORE_SECTOR;
    return n;
}

/* Appends the record in record_buf (its sequence number filled in here)
 * to the head, which has room: STORE_OK once it reads back. The bytes are
 * spent whatever happens. */
static int append_record(int k, u32 len)
{
    u32 n = HEADER + len + 4, addr = sector_addr(head) + append;
    int r;

    wr32(record_buf + 8, next_seq);
    wr32(record_buf + HEADER + len, crc32(record_buf, HEADER + len));
    r = program_verify(addr, record_buf, n);
    append += record_size(len);
    sb_store.append = append;
    next_seq++;
    sb_store.next_seq = next_seq;
    if (r) {
        sb_store.verify_fail++;
        return r;
    }
    key[k].seq = next_seq - 1;
    key[k].addr = addr;
    sb_store.records++;
    return STORE_OK;
}

/* Copies every live record of the sector after the head into the head,
