rep('''            fw_sectors |= 1u << s;''','''            sector_fw[s] = 1;''')
rep('''    for (s = 0; s < STORE_SECTORS; s++)
        if (fw_sectors >> s & 1u)
            scan(s, 2);
    for (s = 0; s < STORE_SECTORS; s++)
        if (fw_sectors >> s & 1u)
            scan(s, 3);''','''    for (s = 0; s < STORE_SECTORS; s++)
        if (sector_fw[s])
            scan(s, 2);
    for (s = 0; s < STORE_SECTORS; s++)
        if (sector_fw[s])
            scan(s, 3);''')
open(p,'w').write(s)
EOF
