import random, sys
sys.path.insert(0, "tools")
import store as st

def full(s):
    for i in range(16):
        s.put(st.PATCH, i, 2, bytes([i]) * 112)
    s.put(st.SELECTION, 0, 1, b"\x05\0\0\0")
    s.put(st.SETTINGS, 0, 4, bytes(42))

def history(sectors, n, size, seed, base_store=True, rewrites=60):
    rnd = random.Random(seed)
    s = st.Store(sectors=sectors, base=0x20000)
    if base_store:
        full(s)
    want = {}
    for i in range(n):
        d = bytes([rnd.randrange(256)]) * size
        s.put_fw(0x80, i, 1, d); want[i] = d
    for r in range(rewrites):
        for _ in range(rnd.randrange(6) if base_store else 0):
            k = rnd.randrange(3)
            if k == 0: s.put(st.PATCH, rnd.randrange(16), 2, bytes([rnd.randrange(256)]) * 112)
            elif k == 1: s.put(st.SELECTION, 0, 1, bytes([rnd.randrange(64), 0, 0, 0]))
            else: s.put(st.SETTINGS, 0, 4, bytes([rnd.randrange(256)]) * 42)
        i = rnd.randrange(n)
        d = bytes([rnd.randrange(256)]) * size
        s.put_fw(0x80, i, 1, d); want[i] = d
    img = st.Image(s.chip(), sectors, 0x20000)
    for i, d in want.items():
        assert img.get_fw(0x80, i) == (1, d), (sectors, n, i)
    return True

for sectors in (5, 16):
    for base_store in (False, True):
        best = 0
        for n in range(1, 16):
            ok = 0
            H = 100 if sectors == 16 else 300
            for seed in range(H):
                try:
                    history(sectors, n, 4096, seed, base_store); ok += 1
                except RuntimeError:
                    pass
            print(sectors, "base" if base_store else "alone", n, "%d/%d" % (ok, H), flush=True)
            if ok < H:
                break
            best = n
        print("=> %d sectors, %s: %d payloads of 4096 every history" % (sectors, "beside full store" if base_store else "alone", best), flush=True)
EOF
