# The store's capacity figures (DESIGN-NOTES), from tools/store.py's model.
import random, sys
sys.path.insert(0, "tools")
import store as st
BASE = 0x20000

def full(s):
    for i in range(16):
        s.put(st.PATCH, i, 2, bytes([i]) * 112)
    s.put(st.SELECTION, 0, 1, b"\x05\0\0\0")
    s.put(st.SETTINGS, 0, 4, bytes(42))

def alone(sectors, size):
    s = st.Store(sectors=sectors, base=BASE)
    try:
        for r in range(40):
            s.put_fw(0x80, 0, 1, bytes([r]) * size)
    except RuntimeError:
        return False
    return st.Image(s.chip(), sectors, BASE).get_fw(0x80, 0) == (1, bytes([39]) * size)

def beside(sectors, size, seed):
    # The base's full store, then 60 rewrites with up to five of the base's
    # saves and sometimes a payload of up to 400 bytes between them.
    rnd = random.Random(seed)
    s = st.Store(sectors=sectors, base=BASE)
    full(s)
    try:
        for r in range(60):
            for _ in range(rnd.randrange(6)):
                k = rnd.randrange(3)
                if k == 0: s.put(st.PATCH, rnd.randrange(16), 2, bytes([rnd.randrange(256)]) * 112)
                elif k == 1: s.put(st.SELECTION, 0, 1, bytes([rnd.randrange(64), 0, 0, 0]))
                else: s.put(st.SETTINGS, 0, 4, bytes([rnd.randrange(256)]) * 42)
            if rnd.randrange(4) == 0:
                s.put_fw(0x81, 0, 1, bytes([r]) * rnd.randrange(1, 401))
            s.put_fw(0x80, 0, 1, bytes([r]) * size)
    except RuntimeError:
        return False
    return st.Image(s.chip(), sectors, BASE).get_fw(0x80, 0) == (1, bytes([59]) * size)

def largest(ok, hi=st.FW_MAX):
    lo, best = 1, 0
    while lo <= hi:
        m = (lo + hi) // 2
        if ok(m): best, lo = m, m + 1
        else: hi = m - 1
    return best

for sectors in [int(a) for a in sys.argv[1:]]:
    a = largest(lambda n: alone(sectors, n))
    H = 100
    b = largest(lambda n: all(beside(sectors, n, seed) for seed in range(H)))
    c = sum(beside(sectors, 4096, seed) for seed in range(300))
    print("%d sectors: alone %d; beside the full store and a small payload %d; 4096 beside the full store %d/300"
          % (sectors, a, b, c), flush=True)
